import hashlib

def calculate_hash(data):
    """
    Efficiently calculate the SHA-256 hash of the given data.
    """
    return hashlib.sha256(data.encode()).hexdigest()

def connect_and_fetch():
    """
    Handle the connection to fetch data from the challenge server responsibly.
    """
    conn = remote('misc.chal.csaw.io', 1337)
    data = []

    while True:
        try:
            line = conn.recvline(timeout=5).decode().strip()
            if line:
                data.append(line)
        except EOFError:
            break

    conn.close()
    return data

def parse_merkle_data(data):
    """
    Parse Merkle Tree data for parent-child relationships.
    """
    relationships = {}

    for entry in data:
        if '=' in entry:
            parts = entry.split('=')
            parent = parts[0].strip()
            children = parts[1].strip().split('+')
            relationships[parent] = [child.strip() for child in children]

    return relationships

def resolve_merkle_root(relationships):
    """
    Compute the Merkle root efficiently by resolving relationships.
    """
    cached = {}

    def resolve(node):
        if node in cached:
            return cached[node]

        if node not in relationships:
            cached[node] = node  # Assume node is a leaf node (precomputed hash)
            return node

        children = relationships[node]
        combined = ''.join(resolve(child) for child in children)
        cached[node] = calculate_hash(combined)
        return cached[node]

    # Identifying the Root Node
    parents = set(relationships.keys())
    children = set(child for sublist in relationships.values() for child in sublist)
    root_candidates = parents - children

    assert len(root_candidates) == 1, "Only one root node expected."
    root = root_candidates.pop()
    return resolve(root)

