    raw_data = connect_and_fetch()
    relationships = parse_merkle_data(raw_data)
    root = resolve_merkle_root(relationships)

    if root.startswith("csawctf{"):
        print("Flag:", root)
    else:
        print(f"Flag: csawctf{{{root}}}")

