from pwn import *
import hashlib
import time

def calculate_hash(data):
    """
    Calculate the SHA-256 hash of the given data.
    """
    return hashlib.sha256(data).hexdigest()

def connect_and_extract_merkle_data():
    """
    Connection handler to fetch data from the Merkle-tree challenge with retry mechanism.
    """
    max_retries = 5
    retry_delay = 3  # seconds
    for attempt in range(max_retries):
        try:
            conn = remote('misc.chal.csaw.io', 1337)

            # Reading and parsing all input data
            responses = []
            while True:
                try:
                    response = conn.recvline(timeout=5).decode()
                    responses.append(response)
                    print(response)
                except EOFError:
                    break
                except Exception as e:
                    print(f"Error receiving data: {e}")
                    break

            conn.close()
            return responses
        except Exception as e:
            print(f"Connection failed on attempt {attempt + 1}: {e}")
            if attempt < max_retries - 1:
                time.sleep(retry_delay)
            else:
                raise


def parse_merkle_tree_data(responses):
    """
    Parse relationships and nodes' details from the challenge data.
    """
    relationships = {}

    # Expected lines have relations: "Parent = Hash(Child1 + Child2)" or similar structures.
    for line in responses:
        line = line.strip()
        if '=' in line:
            # Parse data - assuming standardized challenge output
            parts = line.split('=')
            parent = parts[0].strip()
            children = parts[1].strip().split('+') if '+' in parts[1] else [parts[1].strip()]
            relationships[parent] = children

    return relationships

def compute_merkle_root(relationships):
    """
    Use the intermediate node relations and compute the root hash.
    """

    # Keep resolving relationships until the root is discovered.
    calculated = {}

    def resolve_node(node):
        if node in calculated:
            return calculated[node]
        if node not in relationships:
            # Assume the node is already a predefined leaf.
            calculated[node] = node
            return node

        children = relationships[node]
        combined = b''.join([bytes.fromhex(resolve_node(child)) for child in children])
        calculated[node] = calculate_hash(combined)
        return calculated[node]

    # Find root key (should be the key not referenced as a child)
    all_nodes = set(relationships.keys())
    all_children = set(child for children in relationships.values() for child in children)
    root_candidates = all_nodes - all_children
    assert len(root_candidates) == 1, "There should be exactly one root node."
    root = root_candidates.pop()

    return resolve_node(root)

def main():
    # Step 1: Fetch Data with retries if necessary
    try:
        responses = connect_and_extract_merkle_data()
    except Exception as e:
        print(f"Failed to connect to server: {e}")
        return

    # Step 2: Parse Data for Merkle Relationships
    relationships = parse_merkle_tree_data(responses)

    # Step 3: Compute Root of Merkle
    try:
        merkle_root = compute_merkle_root(relationships)
    except Exception as e:
        print(f"Error in computing Merkle root: {e}")
        return

    # Step 4: Output Flag
    if merkle_root.startswith("csawctf{"):
        print("Flag:", merkle_root)
    else:
        print("Flag:", f"csawctf{{{merkle_root}}}")

if __name__ == '__main__':
    main()

